import { Flow, wfa, trigger, action } from '@servicenow/sdk/automation'
import { IntegerColumn, StringColumn, BooleanColumn } from '@servicenow/sdk/core'

/**
 * This is the EDITED version of the original flow with the SAME sys_id
 *
 * Original: sys_hub_flow_687a54cb829740f6bb2a9ddb7032f419.now.ts
 * This file: Edited version with same Flow sys_id (687a54cb829740f6bb2a9ddb7032f419)
 *
 * Changes made:
 * - Trigger changed from scheduled.daily to record.createdOrUpdated
 * - Table changed from 'incident' to 'problem'
 * - Added sendNotification action at the end
 *
 * Use this file to test the "edit same flow" scenario where a flow is modified
 * but keeps the same sys_id (simulating UI edits to an existing flow)
 */

Flow(
    {
        // SAME sys_id as original flow
        $id: Now.ID['687a54cb829740f6bb2a9ddb7032f419'],

        // Changed name to indicate it's edited
        name: 'Example_1_Daily Incident Processor_v2',

        description: `Triggers - Record Based (Changed from Daily)
Flow Variables
If
IfElse
For Each
Skip Iteration
Set Flow Variables
EndFlow
OOB Action: Look Up Records, Log, Send Notification (Added)`,

        flowVariables: {
            normalPriorityCount: IntegerColumn({
                label: 'normalPriorityCount',
                mandatory: true,
            }),
            processingStatus: StringColumn({
                label: 'processingStatus',
                mandatory: true,
            }),
            highPriorityCount: IntegerColumn({
                label: 'highPriorityCount',
                mandatory: true,
            }),
            shouldContinue: BooleanColumn({
                label: 'shouldContinue',
                mandatory: true,
                default: true,
            }),
            totalProcessed: IntegerColumn({
                label: 'totalProcessed',
                mandatory: true,
            }),
        },
    },
    // CHANGED: Trigger changed from scheduled.daily to record.createdOrUpdated
    wfa.trigger(
        trigger.record.createdOrUpdated,
        {
            $id: Now.ID['96bd6a7ad88542fea2eb94623c4eedba'],
        },
        {
            table: 'problem', // CHANGED: from 'incident' to 'problem'
            condition: 'active=true^assignment_groupISEMPTY^NQpriority=1',
            run_on_extended: 'false',
            run_flow_in: 'any',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
            trigger_strategy: 'once',
        }
    ),
    (_params) => {
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['1edb09e184564a89ad77168b13fcbe6d'],
                annotation: 'Log flow execution start',
                uuid: '1edb09e1-8456-4a89-ad77-168b13fcbe6d',
            },
            {
                log_level: 'info',
                log_message: `Daily Problem Processor started. Querying the active & unassigned Problem OR P1 - ${wfa.dataPill(_params.trigger.current.number, 'string')}`,
            }
        )
        wfa.flowLogic.setFlowVariables(
            {
                annotation: 'Initialize processing counters and status',
                $id: Now.ID['983e1ade48044cbb8659696d072d0439'],
            },
            _params.flowVariables,
            {
                totalProcessed: 0,
                highPriorityCount: 1,
                normalPriorityCount: 1,
                processingStatus: 'STARTED',
                shouldContinue: true,
            }
        )
        const actionInstance_3 = wfa.action(
            action.core.lookUpRecords,
            {
                $id: Now.ID['f311817831d2456d8dc87a00ae5ec749'],
                annotation: 'Query all unassigned problems',
                uuid: 'f3118178-31d2-456d-8dc8-7a00ae5ec749',
            },
            {
                conditions: 'assignment_groupISEMPTY^active=true^NQpriority=1^ORDERBYpriority',
                table: 'problem', // CHANGED: from 'incident' to 'problem'
                sort_type: 'sort_asc',
                sort_column: '',
                max_results: 1000,
            }
        )
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(actionInstance_3.Count, 'integer')}=0`,
                label: 'checking problems are greater than zero',
                annotation: 'Check if there are problems to process',
                $id: Now.ID['0c627e4456294872beae75744c2b5694'],
            },
            () => {
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['07e41fa459694644967b96997252c9f'],
                        uuid: '07e41fa4-5969-4644-9677-b96997252c9f',
                    },
                    {
                        log_level: 'info',
                        log_message: 'No unassigned Problems found',
                    }
                )
                wfa.flowLogic.endFlow({
                    annotation: 'End flow early - no incidents to process',
                    $id: Now.ID['e8d8da55cc30424d9eef50462919b8cd'],
                })
            }
        )
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['591118ecae9b44d682ac472dca1a5d5c'],
                uuid: '591118ec-ae9b-44d6-82ac-472dca1a5d5c',
            },
            {
                log_level: 'info',
                log_message: 'Found unassigned Problems. Beginning processing...',
            }
        )
        wfa.flowLogic.forEach(
            wfa.dataPill(actionInstance_3.Records, 'records'),
            {
                annotation: 'Process each unassigned problems',
                $id: Now.ID['46d167c6cead4a7dacc554b3eed6368e'],
            },
            (item_8) => {
                wfa.flowLogic.if(
                    {
                        condition: `${wfa.dataPill(item_8.priority, 'choice')}=1`,
                        annotation: 'Handle Priority 1 - Critical problems',
                        $id: Now.ID['00097b978c2644278eb80a4321cc2f51'],
                    },
                    () => {
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['d2829217fc644abdbfc4482656ea18a1'],
                                uuid: 'd2829217-fc64-4abd-bfc4-482656ea18a1',
                            },
                            {
                                log_level: 'error',
                                log_message: `CRITICAL: Problem

${wfa.dataPill(item_8, 'reference')}
${wfa.dataPill(item_8.assignment_group, 'reference')}
${wfa.dataPill(item_8.priority, 'choice')}

requires immediate attention!`,
                            }
                        )
                    }
                )
                wfa.flowLogic.elseIf(
                    {
                        condition: `${wfa.dataPill(item_8.priority, 'choice')}=2`,
                        annotation: 'Handle Priority 2 - High priority problems',
                        $id: Now.ID['d6245c6b9c9442f5a336410138f3ea44'],
                    },
                    () => {
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['4b2d862b4dcb481ea15649dddf0c9004'],
                                uuid: '4b2d862b-4dcb-481e-a156-49dddf0c9004',
                            },
                            {
                                log_level: 'warn',
                                log_message: `HIGH PRIORITY: Problem - ${wfa.dataPill(item_8.number, 'string')}`,
                            }
                        )
                    }
                )
                wfa.flowLogic.elseIf(
                    {
                        condition: `${wfa.dataPill(item_8.priority, 'choice')}=3`,
                        annotation: 'Handle Priority 3 - Moderate priority',
                        $id: Now.ID['031692437d94496e8ed7e77809138edc'],
                    },
                    () => {
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['816bb8dfdeae4561a9245c58dae6d98b'],
                                uuid: '816bb8df-deae-4561-a924-5c58dae6d98b',
                            },
                            {
                                log_level: 'info',
                                log_message: `Moderate priority problem identified ${wfa.dataPill(item_8.number, 'string')}`,
                            }
                        )
                    }
                )
                wfa.flowLogic.elseIf(
                    {
                        condition: `${wfa.dataPill(item_8.priority, 'choice')}=4^NQ${wfa.dataPill(item_8.priority, 'choice')}=5`,
                        annotation: 'Else if the Priority is Low or Planning',
                        $id: Now.ID['b565efe3b15af6d0f8774074995d998e'],
                    },
                    () => {
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['1e295392ce774d658a9170520406cd9f'],
                                uuid: '1e295392-ce77-4d65-8a91-70520406cd9f',
                            },
                            {
                                log_level: 'info',
                                log_message: `Low priority problem identified ${wfa.dataPill(item_8.number, 'string')}`,
                            }
                        )
                    }
                )
                wfa.flowLogic.else(
                    {
                        annotation: 'else',
                        $id: Now.ID['79c56f27b15af6d0f8774074995d9973'],
                    },
                    () => {
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['5f22edcad2cd4752b4966a9e17419d3a'],
                                uuid: '5f22edca-d2cd-4752-b496-6a9e17419d3a',
                            },
                            {
                                log_level: 'info',
                                log_message: 'Exiting loop if priority is not set',
                            }
                        )
                        wfa.flowLogic.exitLoop({
                            annotation: 'exit loop',
                            $id: Now.ID['dee56367b15af6d0f8774074995d9952'],
                        })
                    }
                )
            }
        )
        wfa.flowLogic.setFlowVariables(
            {
                annotation: 'Set processing complete status',
                $id: Now.ID['5a60803f42b647c3bcb8366c91cbc3fa'],
            },
            _params.flowVariables,
            {
                processingStatus: 'COMPLETED',
                shouldContinue: false,
            }
        )
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['77ddc9bbeb8c4cceb3d228c9428b115b'],
                annotation: 'Log comprehensive execution summary',
                uuid: '77ddc9bb-eb8c-4cce-b3d2-28c9428b115b',
            },
            {
                log_level: 'info',
                log_message: `
=== DAILY PROBLEM PROCESSOR SUMMARY ===
Status: ${wfa.dataPill(_params.flowVariables.processingStatus, 'string')}
Total Problems Processed: ${wfa.dataPill(_params.flowVariables.totalProcessed, 'integer')}
High Priority (P1/P2): ${wfa.dataPill(_params.flowVariables.highPriorityCount, 'integer')}
Normal/Low Priority (P3/P4): ${wfa.dataPill(_params.flowVariables.normalPriorityCount, 'integer')}
Processing Complete: ${wfa.dataPill(_params.flowVariables.shouldContinue, 'boolean')}
=========================================
                `,
            }
        )

        // NEW: Added notification action
        wfa.action(
            action.core.sendNotification,
            {
                $id: Now.ID['a1b2c3d4e5f6789012345678abcdef90'],
                annotation: 'Send notification after processing',
                uuid: 'a1b2c3d4-e5f6-7890-1234-5678abcdef90',
            },
            {
                record: wfa.dataPill(_params.trigger.current, 'reference'),
                table_name: 'problem',
                notification: '5b429dee7f0232005f58108c3ffa9188',
            }
        )
    }
)
